// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable2Step.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title GuardianCortexAnchor
 * @notice Immutable on-chain record of Merkle tree roots from GuardianAI Cortex.
 *         Each root commits a batch of AI agent decision hashes, providing a
 *         tamper-proof audit trail anchored to an EVM chain.
 *
 * @dev    Uses OpenZeppelin Ownable2Step (safe ownership transfer),
 *         Pausable (emergency stop), and ReentrancyGuard (future-proof).
 *
 *         Only the contract owner (the Guardian deployer wallet) can commit roots.
 *         Verification is public — anyone can check if a leaf is in a committed batch.
 */
contract GuardianCortexAnchor is Ownable2Step, Pausable, ReentrancyGuard {

    // ── Types ────────────────────────────────────────────────────────────

    struct Commitment {
        bytes32  merkleRoot;
        uint256  eventCount;
        bytes32  agentHash;       // keccak256(agentId)
        uint256  periodStart;     // UNIX timestamp
        uint256  periodEnd;       // UNIX timestamp
        uint256  committedAt;     // block.timestamp at commit time
        uint256  blockNumber;     // block.number at commit time
    }

    // ── State ────────────────────────────────────────────────────────────

    /// @notice Maximum commitments per agent (prevents unbounded array growth)
    uint256 public constant MAX_COMMITMENTS_PER_AGENT = 100_000;

    /// @notice Global list of all commitments (append-only)
    Commitment[] public commitments;

    /// @notice agentHash => list of commitment indices
    mapping(bytes32 => uint256[]) public agentCommitments;

    /// @notice merkleRoot => commitment index (0 = not found, actual index + 1)
    mapping(bytes32 => uint256) public rootIndex;

    /// @notice Total number of events anchored across all agents
    uint256 public totalEventsAnchored;

    // ── Events ───────────────────────────────────────────────────────────

    event RootCommitted(
        bytes32 indexed merkleRoot,
        bytes32 indexed agentHash,
        uint256 eventCount,
        uint256 periodStart,
        uint256 periodEnd,
        uint256 commitmentIndex
    );

    // ── Errors ───────────────────────────────────────────────────────────

    error EmptyRoot();
    error ZeroEventCount();
    error InvalidPeriod();
    error RootAlreadyCommitted(bytes32 root);
    error AgentLimitReached(bytes32 agentHash, uint256 limit);
    error InvalidAgentHash();   // Audit I-1

    // ── Constructor ──────────────────────────────────────────────────────

    constructor() Ownable(msg.sender) {}

    // ── Write Functions ──────────────────────────────────────────────────

    /**
     * @notice Commit a Merkle root representing a batch of Cortex events.
     * @param _merkleRoot   The SHA-256 Merkle root hash (as bytes32)
     * @param _eventCount   Number of events in this batch
     * @param _agentHash    keccak256 hash of the agent ID
     * @param _periodStart  UNIX timestamp of the first event in the batch
     * @param _periodEnd    UNIX timestamp of the last event in the batch
     */
    function commitRoot(
        bytes32 _merkleRoot,
        uint256 _eventCount,
        bytes32 _agentHash,
        uint256 _periodStart,
        uint256 _periodEnd
    ) external onlyOwner whenNotPaused nonReentrant {
        if (_merkleRoot == bytes32(0)) revert EmptyRoot();
        if (_eventCount == 0) revert ZeroEventCount();
        if (_agentHash == bytes32(0)) revert InvalidAgentHash();   // Audit I-1
        if (_periodEnd < _periodStart) revert InvalidPeriod();
        if (rootIndex[_merkleRoot] != 0) revert RootAlreadyCommitted(_merkleRoot);
        if (agentCommitments[_agentHash].length >= MAX_COMMITMENTS_PER_AGENT) {
            revert AgentLimitReached(_agentHash, MAX_COMMITMENTS_PER_AGENT);
        }

        uint256 idx = commitments.length;
        commitments.push(Commitment({
            merkleRoot:  _merkleRoot,
            eventCount:  _eventCount,
            agentHash:   _agentHash,
            periodStart: _periodStart,
            periodEnd:   _periodEnd,
            committedAt: block.timestamp,
            blockNumber: block.number
        }));

        rootIndex[_merkleRoot] = idx + 1;  // +1 so 0 means "not found"
        agentCommitments[_agentHash].push(idx);
        totalEventsAnchored += _eventCount;

        emit RootCommitted(
            _merkleRoot, _agentHash, _eventCount,
            _periodStart, _periodEnd, idx
        );
    }

    // ── Read Functions ───────────────────────────────────────────────────

    /**
     * @notice Check if a Merkle root has been committed.
     * @return exists True if the root was committed
     * @return commitment The commitment data (zeroed if not found)
     */
    function getCommitment(bytes32 _merkleRoot)
        external view returns (bool exists, Commitment memory commitment)
    {
        uint256 idx = rootIndex[_merkleRoot];
        if (idx == 0) return (false, commitment);
        return (true, commitments[idx - 1]);
    }

    /**
     * @notice Verify a SHA-256 Merkle inclusion proof on-chain.
     * @param _leaf  The leaf hash
     * @param _proof Array of sibling hashes from leaf to root
     * @param _root  The expected Merkle root
     * @return valid True if the proof checks out
     *
     * @dev Uses sha256 precompile (address 0x02) to match the Python
     *      Merkle tree implementation. Pairs are sorted before hashing
     *      to ensure deterministic ordering.
     *
     * @dev CA-2: Gas cost scales linearly with _proof.length (O(n) sha256
     *      hashes). This is caller-borne — verifyInclusion() is pure and
     *      is not called by any other on-chain contract, so no third party
     *      can grief other callers by inflating proof size. Off-chain RPC
     *      clients should be aware of this for very deep trees.
     */
    function verifyInclusion(
        bytes32 _leaf,
        bytes32[] calldata _proof,
        bytes32 _root
    ) external pure returns (bool valid) {
        bytes32 current = _leaf;
        for (uint256 i = 0; i < _proof.length; i++) {
            bytes32 sibling = _proof[i];
            // Sort pair for deterministic ordering (matches Python implementation)
            if (current > sibling) {
                current = sha256(abi.encodePacked(sibling, current));
            } else {
                current = sha256(abi.encodePacked(current, sibling));
            }
        }
        return current == _root;
    }

    /**
     * @notice Get the total number of commitments.
     */
    function getCommitmentCount() external view returns (uint256) {
        return commitments.length;
    }

    /**
     * @notice Get commitment indices for an agent.
     * @param _agentHash keccak256 hash of the agent ID
     * @return indices Array of commitment indices
     *
     * @dev CA-1: Returns the full agentCommitments[_agentHash] array in one
     *      call. Gas cost scales with the number of commitments made by the
     *      agent (O(n) memory copy). This is caller-borne — getAgentCommitments()
     *      is a view function not called by any other on-chain contract, so no
     *      third party can grief other callers by inflating an agent's array.
     *      Off-chain callers querying very active agents should be aware of
     *      the RPC response size. A paginated variant can be added if needed.
     */
    function getAgentCommitments(bytes32 _agentHash)
        external view returns (uint256[] memory indices)
    {
        return agentCommitments[_agentHash];
    }

    // ── Admin Functions ──────────────────────────────────────────────────

    /**
     * @notice Pause the contract (emergency stop). Only owner.
     */
    function pause() external onlyOwner { _pause(); }

    /**
     * @notice Unpause the contract. Only owner.
     */
    function unpause() external onlyOwner { _unpause(); }
}

contracts/GuardianInterlockRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable2Step.sol";
import "@openzeppelin/contracts/utils/Pausable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title GuardianInterlockRegistry
 * @notice Stores cross-agent interlock proofs on-chain, enabling mutual verification
 *         of interaction history between autonomous AI agents.
 *
 * @dev    IR-2 fix: Added soft-revoke mechanism (revokeInterlock) so that a bad
 *         registration — e.g. one produced by a compromised owner key with fabricated
 *         agent/proof data — can be corrected without deleting the historical record.
 *
 *         Design rationale: Interlock proofs are intentionally append-only (the
 *         InterlockRegistered event is permanent on-chain, providing non-repudiation).
 *         However, permanence of the *event log* is distinct from permanence of
 *         *current validity* — the same distinction made by GuardianInsuranceLedger's
 *         revokeCertificate(). A revoked record remains inspectable via getInterlock()
 *         but verifyInterlock() reverts InterlockAlreadyRevoked, so downstream
 *         protocols querying proof validity get the correct answer.
 *
 *         revokeInterlock() is whenNotPaused: revocation during an active pause/
 *         incident-response window is dangerous — a compromised owner key could use
 *         revocation as a cover-up tool to erase evidence of fabricated interlocks
 *         before the pause can be lifted. Requiring the contract to be unpaused to
 *         revoke ensures the emergency-stop and the corrective-action paths remain
 *         independent. (This matches InsuranceLedger's revokeCertificate() precedent.)
 */
contract GuardianInterlockRegistry is Ownable2Step, Pausable, ReentrancyGuard {

    // ── Types ────────────────────────────────────────────────────────────

    struct InterlockProof {
        bytes32 agentA;       // keccak256(agentA_id)
        bytes32 agentB;       // keccak256(agentB_id)
        bytes32 proofHash;
        uint256 nonce;
        uint256 registeredAt;
        bool    revoked;      // true after revokeInterlock(); record preserved for history
    }

    // ── State ────────────────────────────────────────────────────────────

    /// @notice Maximum interlocks to prevent unbounded array growth (Audit M-3)
    uint256 public constant MAX_INTERLOCKS = 100_000;

    /// @notice Maps interlockId to its proof details
    mapping(bytes32 => InterlockProof) public registry;

    /// @notice List of all registered interlock IDs
    bytes32[] public interlockIds;

    // ── Events ───────────────────────────────────────────────────────────

    event InterlockRegistered(
        bytes32 indexed interlockId,
        bytes32 indexed agentA,
        bytes32 indexed agentB,
        bytes32 proofHash,
        uint256 nonce
    );

    /// @notice Emitted when an owner revokes a previously registered interlock.
    ///         The record is preserved in storage and inspectable via getInterlock();
    ///         only verifyInterlock() treats a revoked record as invalid.
    event InterlockRevoked(bytes32 indexed interlockId);

    // ── Errors ───────────────────────────────────────────────────────────

    error InterlockAlreadyExists(bytes32 interlockId);
    error InvalidAgentHash();
    error InvalidProofHash();
    error InterlockNotFound(bytes32 interlockId);
    /// @notice Thrown by verifyInterlock() and revokeInterlock() when the record
    ///         has already been revoked.
    error InterlockAlreadyRevoked(bytes32 interlockId);
    /// @notice Audit M-3: array cap reached
    error InterlockLimitReached();

    // ── Constructor ──────────────────────────────────────────────────────

    constructor() Ownable(msg.sender) {}

    // ── Write Functions ──────────────────────────────────────────────────

    /**
     * @notice Register a mutual interlock proof between two agents.
     * @param _agentA    keccak256 hash of agent A ID
     * @param _agentB    keccak256 hash of agent B ID
     * @param _proofHash Hash of the interlock interaction proof
     * @param _nonce     Nonce for uniqueness
     * @return interlockId The computed unique ID of this interlock
     */
    function registerInterlock(
        bytes32 _agentA,
        bytes32 _agentB,
        bytes32 _proofHash,
        uint256 _nonce
    ) external onlyOwner whenNotPaused nonReentrant returns (bytes32 interlockId) {
        if (_agentA == bytes32(0) || _agentB == bytes32(0)) revert InvalidAgentHash();
        if (_proofHash == bytes32(0)) revert InvalidProofHash();
        if (interlockIds.length >= MAX_INTERLOCKS) revert InterlockLimitReached();  // Audit M-3

        interlockId = keccak256(abi.encodePacked(_agentA, _agentB, _proofHash, _nonce));
        if (registry[interlockId].registeredAt != 0) revert InterlockAlreadyExists(interlockId);

        registry[interlockId] = InterlockProof({
            agentA:       _agentA,
            agentB:       _agentB,
            proofHash:    _proofHash,
            nonce:        _nonce,
            registeredAt: block.timestamp,
            revoked:      false
        });

        interlockIds.push(interlockId);

        emit InterlockRegistered(interlockId, _agentA, _agentB, _proofHash, _nonce);
    }

    // ── Write Functions (admin) ──────────────────────────────────────────

    /**
     * @notice Revoke a previously registered interlock proof.
     * @param _interlockId The ID of the interlock to revoke.
     *
     * @dev    The record is marked revoked in storage but NOT deleted.
     *         getInterlock() continues to return the full record including
     *         revoked = true, preserving the tamper-evident audit trail.
     *         verifyInterlock() reverts InterlockAlreadyRevoked for revoked records.
     *
     *         whenNotPaused: prevents a compromised owner key from using revocation
     *         as a cover-up tool during an active incident (see contract NatSpec).
     */
    function revokeInterlock(bytes32 _interlockId) external onlyOwner whenNotPaused {
        InterlockProof storage proof = registry[_interlockId];
        if (proof.registeredAt == 0) revert InterlockNotFound(_interlockId);
        if (proof.revoked) revert InterlockAlreadyRevoked(_interlockId);
        proof.revoked = true;
        emit InterlockRevoked(_interlockId);
    }

    // ── Read Functions ───────────────────────────────────────────────────

    /**
     * @notice Verify and return the proof hash for a registered, non-revoked interlock.
     * @param _interlockId The ID of the interlock.
     * @return proofHash   The stored proof hash.
     * @dev    Reverts InterlockAlreadyRevoked if the record has been revoked.
     *         Use getInterlock() to inspect revoked records.
     */
    function verifyInterlock(bytes32 _interlockId) external view returns (bytes32 proofHash) {
        InterlockProof memory proof = registry[_interlockId];
        if (proof.registeredAt == 0) revert InterlockNotFound(_interlockId);
        if (proof.revoked) revert InterlockAlreadyRevoked(_interlockId);
        return proof.proofHash;
    }

    /**
     * @notice Get details of a registered interlock proof.
     */
    function getInterlock(bytes32 _interlockId) external view returns (InterlockProof memory) {
        InterlockProof memory proof = registry[_interlockId];
        if (proof.registeredAt == 0) revert InterlockNotFound(_interlockId);
        return proof;
    }

    /**
     * @notice Get total number of registered interlocks.
     */
    function getInterlockCount() external view returns (uint256) {
        return interlockIds.length;
    }

    // ── Admin Functions ──────────────────────────────────────────────────

    function pause() external onlyOwner { _pause(); }
    function unpause() external onlyOwner { _unpause(); }
}

